INSERT INTO PDP_backup VALUES(1542,1729156689656,1731252251858,629,473,951,2024,'[{"text":"Dispensa dalla lettura ad alta voce in classe","selected":false},{"text":"Dispensa uso corsivo e stampato minuscolo","selected":false},{"text":"Dispensa dalla scrittura sotto dettatura di testi e/o appunti. Dispensa dal ricopiare testi o espressioni matematiche dalla lavagna","selected":false},{"text":"Dispensa dallo studio mnemonico (delle forme verbali, delle poesie)","selected":false},{"text":"Dispensa da un eccessivo carico di compiti con riadattamento e riduzione delle pagine da studiare, senza modificare gli obiettivi","selected":true},{"text":"Dispensa dalla sovrapposizione di compiti e interrogazioni di più materie","selected":true},{"text":"Dispensa parziale dallo studio della lingua straniera in forma scritta, che verrà valutata in percentuale minore rispetto all’orale non considerando errori ortografici e di spelling","selected":false},{"text":"Integrazione dei libri di testo con materiale fornito dall''insegnante su supporto vario","selected":false},{"text":"Nelle verifiche scritte, utilizzo di domande a risposta multipla e (con possibilità di completamento e/o arricchimento con una discussione orale); riduzione al minimo delle domande a risposte aperte","selected":false},{"text":"Parziale sostituzione o completamento delle verifiche scritte con prove orali","selected":false}]','[{"text":"Utilizzo di computer e tablet","selected":true},{"text":"Utilizzo di programmi di video-scrittura con correttore ortografico (possibilmente vocale) e con tecnologie di sintesi vocale (anche per le lingue straniere)","selected":true},{"text":"Utilizzo di risorse audio (file audio digitali, audiolibri…)","selected":true},{"text":"Utilizzo di ausili per il calcolo (tavola pitagorica, linee dei numeri…) ed eventualmente della calcolatrice","selected":false},{"text":"Utilizzo di schemi, formulari, tabelle, mappe e diagrammi di flusso precedentemente validate e firmate dall’insegnante come supporto durante compiti e verifiche scritte .Eventualmente anche su supporto digitalizzato (presentazioni multimediali), per facilitare il recupero delle informazioni","selected":true},{"text":"Utilizzo di dizionari digitali (cd rom, risorse online)","selected":false},{"text":"Utilizzo di software didattici e compensativi (free e/o commerciali)","selected":false}]','[{"text":"Valutare per formare (orientare il processo di insegnamento-apprendimento)","selected":true},{"text":"Valorizzare il processo di apprendimento dell’allievo e non valutare esclusivamente il prodotto/risultato","selected":false},{"text":"Predisporre verifiche scalari (graduate, con difficoltà crescente)","selected":false},{"text":"Programmare con un anticipo di almeno una settimana  la data delle verifiche","selected":true},{"text":"Prevedere verifiche orali a compensazione di quelle scritte (soprattutto per la lingua straniera) ove necessario","selected":false},{"text":"Verificare che la consegna sia stata compresa correttamente","selected":true},{"text":"Valutare tenendo conto maggiormente del contenuto piuttosto che della forma (errori di ortografia, precisione del tratto e pulizia nel disegno)","selected":false},{"text":"Valutazione dei procedimenti e non dei calcoli nella risoluzione dei problemi","selected":false},{"text":"Introdurre prove informatizzate","selected":false},{"text":"Nelle verifiche, riduzione e adattamento del numero degli esercizi senza modificare gli obiettivi","selected":false}]','','Si precisa che qualora si utilizzi il pc  per le prove di verifica dovranno essere usati solo programmi OFFLINE e in modalità AEREO. Inoltre le mappe e gli schemi utilizzati dallo studente, dovranno esser consegnati in formato CARTACEO e validati anzitempo dal docente con una scadenza di almeno una settimana prima della prova orale o scritta. Inoltre, le mappe d''ausilio alle verifiche (orali o scritte) dovranno seguire le regolamentazioni definite in aula e non dovranno essere appunti, parti del quaderno o riassunti.','','','',1,1,0,'[{"text":"Concedere la possibilità di uscire dalla classe per scaricare la tensione accumulata","selected":false},{"text":"Fare brevi pause nelle spiegazioni per dare la possibilità di recuperare le risorse attentive , ridurre lo sforzo,  migliorare la comprensione e la memorizzazione","selected":false},{"text":"Rendere l’alunno parte attiva della lezione","selected":false},{"text":"Disporre il banco non troppo distante dalla cattedra e , comunque lontano da fonti di distrazione","selected":false},{"text":"Strutturare le attività proposte secondo tempistiche e step ben chiari ed esplicitati, in modo da favorire nel ragazzo una maggiore comprensione di quanto richiesto","selected":false}]','[{"text":"Incentivare e lavorare su collaborazione, cooperazione e clima di classe","selected":true},{"text":"Adattare i propri stili di comunicazione, le forme di lezione e gli spazi di apprendimento","selected":true},{"text":"Potenziare le strategie logico-visive (forme di schematizzazione e organizzazione anticipata della conoscenza e, in particolare, i diagrammi, le linee del tempo, le illustrazioni significative e le flashcard delle regole)","selected":true},{"text":"Sviluppare la METACOGNIZIONE (consapevolezza i rispetto ai propri processi cognitivI e stili di apprendimento)","selected":true},{"text":"Cooperative learning","selected":true}]');
