INSERT INTO PDP_backup VALUES(3353,1759074981299,1764253617412,629,1343,961,2025,'[{"text":"Dispensa dalla lettura ad alta voce in classe","selected":false},{"text":"Dispensa uso corsivo e stampato minuscolo","selected":false},{"text":"Dispensa dalla scrittura sotto dettatura di testi e/o appunti. Dispensa dal ricopiare testi o espressioni matematiche dalla lavagna","selected":false},{"text":"Dispensa dallo studio mnemonico (delle forme verbali, delle poesie)","selected":false},{"text":"Dispensa da un eccessivo carico di compiti con riadattamento e riduzione delle pagine da studiare, senza modificare gli obiettivi","selected":false},{"text":"Dispensa dalla sovrapposizione di compiti e interrogazioni di più materie","selected":true},{"text":"Dispensa parziale dallo studio della lingua straniera in forma scritta, che verrà valutata in percentuale minore rispetto all’orale non considerando errori ortografici e di spelling","selected":false},{"text":"Integrazione dei libri di testo con materiale fornito dall''insegnante su supporto vario","selected":false},{"text":"Nelle verifiche scritte, utilizzo di domande a risposta multipla e (con possibilità di completamento e/o arricchimento con una discussione orale); riduzione al minimo delle domande a risposte aperte","selected":false},{"text":"Parziale sostituzione o completamento delle verifiche scritte con prove orali","selected":false}]','[{"text":"Utilizzo di computer e tablet","selected":false},{"text":"Utilizzo di programmi di video-scrittura con correttore ortografico (possibilmente vocale) e con tecnologie di sintesi vocale (anche per le lingue straniere)","selected":false},{"text":"Utilizzo di risorse audio (file audio digitali, audiolibri…)","selected":false},{"text":"Utilizzo di ausili per il calcolo (tavola pitagorica, linee dei numeri…) ed eventualmente della calcolatrice","selected":false},{"text":"Utilizzo di schemi, formulari, tabelle, mappe e diagrammi di flusso precedentemente validate e firmate dall’insegna